void ui_event_Home(lv_event_t * e)
{
    lv_event_code_t event_code = lv_event_get_code(e);

    if(event_code == LV_EVENT_GESTURE &&  lv_indev_get_gesture_dir(lv_indev_active()) == LV_DIR_LEFT) {
        lv_indev_wait_release(lv_indev_active());
        _ui_flag_modify(ui_FirstPage, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_ADD);
        _ui_flag_modify(ui_FollowingPage, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_REMOVE);
    }
    if(event_code == LV_EVENT_GESTURE &&  lv_indev_get_gesture_dir(lv_indev_active()) == LV_DIR_RIGHT) {
        lv_indev_wait_release(lv_indev_active());
        _ui_flag_modify(ui_FollowingPage, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_ADD);
        _ui_flag_modify(ui_FirstPage, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_REMOVE);
    }
}

void ui_event_AppItemSettings_appItemImage(lv_event_t * e)
{
    lv_event_code_t event_code = lv_event_get_code(e);

    if(event_code == LV_EVENT_PRESSED) {
        videofocusmanager_open_app(APP_SETTINGS);
    }

}

void ui_event_AppItemBluetooth_appItemImage(lv_event_t * e)
{
    lv_event_code_t event_code = lv_event_get_code(e);

    if(event_code == LV_EVENT_PRESSED) {
        /* Initialize Bluetooth lazily on first tap so it stays off the
         * startup/first-frame path. bt_app_init_async() is idempotent. */
#ifdef HCN_APP_HAVE_BT
        BtAppConfig bt_config = { "/data/bluetoothconfiguration.cfg" };
        bt_app_init_async(&bt_config);
#endif
        videofocusmanager_open_app(APP_BLUETOOTH);
    }
}

void ui_event_AppItemMusic_appItemImage(lv_event_t * e)
{
    lv_event_code_t event_code = lv_event_get_code(e);

    if(event_code == LV_EVENT_PRESSED) {
        int ret = videofocusmanager_open_app(APP_MUSIC);
        syslog(LOG_INFO, "music app open requested, ret=%d", ret);
    }
}

