void ui_event_AppItemCarPlayApp_appItemImage(lv_event_t * e)
{
    lv_event_code_t event_code = lv_event_get_code(e);

    //lv_log("%s", __func__);

    if(event_code == LV_EVENT_PRESSED) {
#ifdef LVGL_BUILD_CARPLAY
        CarplayApp* cp = carplayapp_get_instance();
        if (carplayapp_is_connected(cp) && !carplayapp_is_show_limit(cp)) {
            videofocusmanager_open_app(APP_CARPLAY);
            carplayapp_request_ui(cp);
        }
#endif
    }
}

void ui_event_AppItemCarPlaySetting_appItemImage(lv_event_t * e)
{
    lv_event_code_t event_code = lv_event_get_code(e);

    //lv_log("%s", __func__);

    if(event_code == LV_EVENT_PRESSED) {
        videofocusmanager_open_app(APP_CARPLAY_SETTINGS);
    }
}

void ui_event_AppItemAndroidAuto_appItemImage(lv_event_t * e)
{
    lv_event_code_t event_code = lv_event_get_code(e);

    if(event_code == LV_EVENT_PRESSED) {
        /* Initialize AndroidAuto lazily on first tap so it stays off the
         * startup/first-frame path. aa_app_init() is idempotent. */
#ifdef HCN_APP_HAVE_AA
        aa_app_init();
        aa_app_open_projection();
#endif
    }
}

void ui_event_AppItemAndroidAutoSettings_appItemImage(lv_event_t * e)
{
    lv_event_code_t event_code = lv_event_get_code(e);

    if(event_code == LV_EVENT_PRESSED) {
#ifdef HCN_APP_HAVE_AA
        aa_app_init();
        aa_app_open_settings();
#endif
    }
}

